import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import "./App.css";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");
      setData(res.data);
    } catch (err) {
      console.log("ERROR API:", err);
    } finally {
      setLoading(false);
    }
  };

  const latest = data.length > 0 ? data[0] : null;

  // ✅ cuma 1 chartData
  const chartData = {
    labels: data.map(d => d.waktu).slice(-10),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).slice(-10),
        borderColor: "#22c55e",
        tension: 0.4
      }
    ]
  };

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f59e0b";
    return "#22c55e";
  };

  // NOTE: Keeping the alerts can be disruptive during polling.
  // If you still want them, we can switch to a toast later.

  return (
    <div className="layout">
      <aside className="sidebar">
        <div className="sidebar__brand">
          <div className="sidebar__logo">⚡</div>
          <div className="sidebar__name">Hematrik</div>
        </div>

        <nav className="nav">
          <button
            className={page === "dashboard" ? "nav__item nav__item--active" : "nav__item"}
            onClick={() => setPage("dashboard")}
            type="button"
          >
            Dashboard
          </button>
          <button
            className={page === "monitoring" ? "nav__item nav__item--active" : "nav__item"}
            onClick={() => setPage("monitoring")}
            type="button"
          >
            Monitoring
          </button>
          <button
            className={page === "history" ? "nav__item nav__item--active" : "nav__item"}
            onClick={() => setPage("history")}
            type="button"
          >
            History
          </button>
        </nav>
      </aside>

      <main className="content">
        <header className="topbar">
          <div className="topbar__title">
            {page === "dashboard" && "Dashboard Monitoring"}
            {page === "monitoring" && "CCTV AI Monitoring"}
            {page === "history" && "History"}
          </div>

          <div className="topbar__actions">
            <div className="search">
              <input
                className="search__input"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search"
                aria-label="Search"
              />
            </div>
          </div>
        </header>

        <div className="page">
          {loading && <div className="loading">Loading data...</div>}

          {/* DASHBOARD */}
          {page === "dashboard" && latest && !loading && (
            <>
              <div className="banner" style={{ borderLeftColor: getColor(latest.kondisi) }}>
                <div className="banner__label">Status</div>
                <div className="banner__text">{latest.notifikasi}</div>
              </div>

              <section className="grid">
                <div className="card">
                  <div className="card__title">People Detected</div>
                  <div className="card__value">{latest.jumlah_orang}</div>
                </div>

                <div className="card">
                  <div className="card__title">Room Activity</div>
                  <div className="card__value">
                    <span className="pill pill--muted">{latest.kondisi}</span>
                  </div>
                  <div className="card__meta" style={{ color: getColor(latest.kondisi) }}>
                    {latest.kondisi}
                  </div>
                </div>

                <div className="card">
                  <div className="card__title">Device Status</div>
                  <div className="device">
                    <div className="device__row">
                      <div className="device__name">Listrik</div>
                      <div className={latest.status_listrik === "ON" ? "device__state device__state--on" : "device__state device__state--off"}>
                        {latest.status_listrik}
                      </div>
                    </div>
                    <div className="device__hint">Updated: {latest.waktu}</div>
                  </div>
                </div>
              </section>

              <section className="card card--chart">
                <div className="card__title">Room Activity</div>
                <div className="chart">
                  <Line data={chartData} />
                </div>
              </section>
            </>
          )}

          {/* MONITORING */}
          {page === "monitoring" && latest && !loading && (
            <section className="monitor">
              <div className="monitor__media">
                <img
                  src="http://127.0.0.1:8000/stream"
                  alt="CCTV"
                  className="monitor__image"
                />
              </div>
              <div className="monitor__side">
                <div className="card">
                  <div className="card__title">People Detected</div>
                  <div className="card__value">{latest.jumlah_orang}</div>
                </div>
                <div className="card">
                  <div className="card__title">Listrik</div>
                  <div className="card__value">
                    <span className={latest.status_listrik === "ON" ? "pill pill--on" : "pill pill--off"}>
                      {latest.status_listrik}
                    </span>
                  </div>
                </div>
                <div className="card">
                  <div className="card__title">Kondisi</div>
                  <div className="card__value" style={{ color: getColor(latest.kondisi) }}>
                    {latest.kondisi}
                  </div>
                  <div className="card__meta">{latest.notifikasi}</div>
                </div>
              </div>
            </section>
          )}

          {/* HISTORY */}
          {page === "history" && !loading && (
            <section className="card">
              <div className="card__title">Riwayat Data</div>
              <div className="tableWrap">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Waktu</th>
                      <th>Orang</th>
                      <th>Listrik</th>
                      <th>Kondisi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data
                      .filter((d) => {
                        if (!search.trim()) return true;
                        const q = search.toLowerCase();
                        return (
                          String(d.waktu ?? "").toLowerCase().includes(q) ||
                          String(d.jumlah_orang ?? "").toLowerCase().includes(q) ||
                          String(d.status_listrik ?? "").toLowerCase().includes(q) ||
                          String(d.kondisi ?? "").toLowerCase().includes(q)
                        );
                      })
                      .map((d) => (
                        <tr key={d.id}>
                          <td>{d.waktu}</td>
                          <td>{d.jumlah_orang}</td>
                          <td>{d.status_listrik}</td>
                          <td style={{ color: getColor(d.kondisi) }}>{d.kondisi}</td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </div>
            </section>
          )}

          {!loading && !latest && <div className="loading">No data yet.</div>}
        </div>
      </main>
    </div>
  );
}

export default App;
